"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6824],{26824:d=>{d.exports=JSON.parse('{"schemaVersion":1,"locale":"ru","slug":"06-podushka","title":"Урок 06. Подушка: Сколько, где и как собрать с нуля","sourceFingerprint":"55fde8f1761a7584c3602edb66345570724830e9c922944a0e40fdb1ac988b11","blocks":[{"id":"b001","markdown":"## Подушка"},{"id":"b002","markdown":"Сколько, где и как собрать с нуля"},{"id":"b003","markdown":"Финансовая подушка это резервная копия твоей жизни. Пока телефон работает, бэкап фотографий кажется лишней морокой. Вспоминают о нём в тот день, когда телефон утонул или его украли. Если копия была, ты теряешь вечер на восстановление. Если не было, теряешь всё."},{"id":"b004","markdown":"Сломалась машина, сократили на работе, срочно нужно лечить зуб. Без подушки каждая такая история решается кредиткой под 50%. С подушкой это просто расход, после которого ты спокойно пополняешь запас. Зарабатывать на подушке никто не собирается. Её работа в том, чтобы тебе не пришлось занимать."},{"id":"b005","markdown":"### Сколько нужно"},{"id":"b006","markdown":"Обычный ориентир от 3 до 6 месяцев обязательных расходов. Именно обязательных, то есть корзина 1 из урока 2: жильё, еда, транспорт, связь, платежи по кредитам и лекарства. Если что-то случится с работой, от ресторанов и поездок ты на время откажешься, от аренды и еды нет."},{"id":"b007","markdown":"3–6 месяцев примерно соответствуют сроку, за который большинство находит новую работу или приходит в себя после серьёзной неприятности. 3 месяцев обычно хватает, если в семье 2 стабильных дохода, работу в твоей отрасли легко найти и нет ипотеки и иждивенцев."},{"id":"b008","markdown":"6 месяцев и больше нужно, если доход нерегулярный: фриланс, самозанятость, бизнес или большая доля премий. А ещё если ты единственный кормилец, есть ипотека или дети, либо у тебя узкая специальность и работу ищут долго. Пример: обязательные расходы 70 000 ₽ в месяц. Подушка на 3 месяца 210 000 ₽, на 6 месяцев 420 000 ₽."},{"id":"b009","markdown":"В уроке 1 был опрос Russian Field : у тех россиян, у кого есть сбережения, медианный запас около 3,5 месяца. Даже минимальная подушка ставит тебя в лучшую половину."},{"id":"b010","markdown":"### Как собрать с нуля"},{"id":"b011","markdown":"Сумма в 200–400 тысяч может пугать, поэтому подушку собирают по этапам, и каждый уже делает тебя устойчивее."},{"id":"b012","markdown":"- 1 месяц обязательных расходов. Этот этап был в уроке 5. Если есть дорогие долги, после него переключаешься на их погашение."},{"id":"b013","markdown":"- 3 месяца, когда дорогих долгов уже нет. Это базовая защита на случай потери работы."},{"id":"b014","markdown":"- 6 месяцев, особенно если ты в группе риска из списка выше."},{"id":"b015","markdown":"Пополнять подушку можно из 3 источников. Первый: доля накоплений, то есть автоперевод из урока 3. Второй: разовые деньги вроде премий, вычетов из урока 10, подарков и продажи ненужных вещей. Третий: бывшие утечки. С разовыми деньгами удобно правило \xabполовину в подушку, половину себе\xbb."},{"id":"b016","markdown":"Сколько нужно на подушку и где её держать?"},{"id":"b017","markdown":"Обязательные расходы в месяц (корзина 1) 70\xa0000 ₽ Что про тебя"},{"id":"b018","markdown":"Доход нерегулярный Ты единственный кормилец Есть ипотека или дети Узкая специальность 210\xa0000 ₽"},{"id":"b019","markdown":"3 месяца обязательных расходов"},{"id":"b020","markdown":"Этап 1: месяц расходов 70\xa0000 ₽ Этап 2: 3 месяца 210\xa0000 ₽ На накопительном счёте (около месяца) 70\xa0000 ₽ На вкладе с частичным снятием 140\xa0000 ₽ 3 месяцев хватит, если в семье 2 стабильных дохода и работу легко найти. Две части держи в разных банках."},{"id":"b021","markdown":"### Где хранить"},{"id":"b022","markdown":"К подушке 3 требования, и доходность среди них не главное. Деньги должны быть доступны за 1–2 дня, их нельзя потерять из-за падения рынка, и на них должны начисляться проценты, чтобы инфляция не съедала запас. Подушку удобно делить на 2 части, как деньги в кошельке и в копилке. Кошелёк всегда под рукой, копилка надёжнее, но до неё дольше добираться."},{"id":"b023","markdown":"#### Первая часть: накопительный счёт"},{"id":"b024","markdown":"Около месяца расходов. Снимать и пополнять можно в любой момент без потери процентов."},{"id":"b025","markdown":"Выбирай счёт с процентами на ежедневный остаток. Есть счета, где проценты считают с минимального остатка за месяц. Ставка там часто выше, но стоит снять деньги в середине месяца, и на снятую сумму за весь месяц ничего не начислят. Эту часть как раз иногда снимают, так что такой счёт ей не подходит."},{"id":"b026","markdown":"Минус накопительного счёта в том, что банк может поменять ставку в любой день."},{"id":"b027","markdown":"#### Вторая часть: вклад с частичным снятием"},{"id":"b028","markdown":"Всё остальное. Ставка зафиксирована на весь срок, и при снижении ставок, как сейчас, это полезно. Выбирай вклад на 3–6 месяцев, где часть денег можно снять без потери процентов: на обычном срочном вкладе при досрочном закрытии проценты пересчитывают почти до нуля."},{"id":"b029","markdown":"#### Не в одном месте"},{"id":"b030","markdown":"Запасной ключ от квартиры не держат на той же связке, что и основной, иначе потеряешь оба сразу. Его оставляют у родителей или у соседей. С подушкой так же: обе её части лучше держать в разных банках плюс небольшую сумму наличными дома. Если один банк заблокирует карту или его приложение перестанет работать, остальные части подушки останутся доступны."},{"id":"b031","markdown":"ПОДУШКА НЕ В ОДНОМ МЕСТЕ БАНК 1 НАКОПИТЕЛЬНЫЙ: ~1 МЕСЯЦ БАНК 2 ВКЛАД: ОСТАЛЬНОЕ, МОЖНО СНЯТЬ ЧАСТЬ ₽ НАЛИЧНЫЕ ДОМА НА НЕДЕЛЮ-ДВЕ ЗАПАСНОЙ КЛЮЧ НЕ НА ОДНОЙ СВЯЗКЕ"},{"id":"b032","markdown":"### Страхование вкладов"},{"id":"b033","markdown":"Деньги на вкладах и счетах в банке из системы страхования вкладов застрахованы государством через Агентство по страхованию вкладов (АСВ). Лимит 1,4 млн ₽ на одного человека в одном банке, и проценты входят в эту сумму. Если у банка отзовут лицензию, АСВ вернёт деньги в пределах лимита."},{"id":"b034","markdown":"Большинству подушек этого хватает с запасом. Если сумма подбирается к лимиту, раздели её между 2 банками. Входит ли банк в систему, можно проверить на сайте АСВ."},{"id":"b035","markdown":"### В какой валюте"},{"id":"b036","markdown":"Подушка хранится в той валюте, в которой ты тратишь. Если аренду, еду и стоматолога ты оплачиваешь в рублях, подушка должна быть в рублях."},{"id":"b037","markdown":"У резервной копии есть ещё одно требование: из неё должно быть можно быстро восстановиться. Копия, которую в день аварии придётся неделю вытаскивать с другого конца света, почти бесполезна. С валютой \xabна всякий случай\xbb так же. В день, когда срочно нужны деньги, её придётся сначала продать, и не факт, что по выгодному курсу. Поэтому валюта нужна для защиты накоплений, и это тема следующего модуля, а не подушки."},{"id":"b038","markdown":"Исключение: регулярные расходы в другой валюте, например учёба ребёнка за границей. Тогда часть подушки логично держать в ней. Наличные дома на неделю-две жизни это тот самый запасной ключ. Они выручат, если карты и приложения временно не работают."},{"id":"b039","markdown":"### Что подушкой не считается"},{"id":"b040","markdown":"Кредитный лимит (это чужие деньги под 50%). Акции, облигации и фонды, которые могут подешеветь ровно тогда, когда понадобятся деньги. Криптовалюта, по тем же причинам, только сильнее. Квартира и машина, которые быстро и без потерь не продашь. И \xabпопрошу у родителей\xbb, потому что это надежда, а не деньги."},{"id":"b041","markdown":"### Когда её трогать"},{"id":"b042","markdown":"Подушка нужна для ситуаций, которые одновременно непредвиденные, срочные и необходимые. Например, потеря работы, лечение, срочный ремонт или поломка машины, без которой не добраться до работы. Распродажа, новый телефон и горящая путёвка сюда не относятся, для них есть цели из урока 3. Если взял из подушки, сначала верни туда деньги. Пока она не восстановлена, это снова главный приоритет."},{"id":"b043","markdown":"### Налог на проценты"},{"id":"b044","markdown":"Если накопления большие, стоит знать про налог. С процентов по вкладам и накопительным счетам платят НДФЛ, но только с суммы выше необлагаемого лимита. Лимит считают так: 1 млн ₽ умножить на максимальную ключевую ставку на 1-е число каждого месяца года."},{"id":"b045","markdown":"На 1 января 2026 года ставка была 16%, и выше в течение года она не поднималась. Значит, за 2026 год без налога можно получить 160 000 ₽ процентов по всем вкладам во всех банках вместе. При ставках около 13% это примерно 1,2 млн ₽ накоплений, и если у тебя меньше, налог тебя не касается."},{"id":"b046","markdown":"Налог считает налоговая и присылает уведомление. За 2026 год его нужно заплатить до 1 декабря 2027 года."},{"id":"b047","markdown":"### Самое главное"},{"id":"b048","markdown":"- Подушка это 3–6 месяцев обязательных расходов. Её задача избавить тебя от необходимости занимать."},{"id":"b049","markdown":"- Собирай по этапам: 1 месяц, потом 3, потом 6."},{"id":"b050","markdown":"- Храни на накопительном счёте с процентами на ежедневный остаток или на вкладе с частичным снятием, в той валюте, в которой тратишь."},{"id":"b051","markdown":"- Страховой лимит АСВ 1,4 млн ₽ на один банк."},{"id":"b052","markdown":"Собранную подушку теперь нужно уберечь. Чаще всего её теряют не из-за инфляции или кризиса, а из-за одного телефонного звонка, и об этом следующий урок."}],"terms":[{"id":"asv","term":"АСВ (Агентство по страхованию вкладов)","definition":"государственный механизм, который выплачивает вкладчику до 1,4 млн ₽ на один банк, если банк лишился лицензии или обанкротился. Поэтому держать в одном банке больше этой суммы неразумно"},{"id":"inflyatsiya","term":"Инфляция","definition":"рост общего уровня цен. На деле: денег стало больше, товаров столько же — каждый стоит дороже. Ты не стал богаче, просто ценники выросли"},{"id":"klyuchevaya-stavka","term":"Ключевая ставка","definition":"процент, под который ЦБ кредитует банки. Главный инструмент денежно-кредитной политики и \xabцена денег\xbb в экономике. Ставка вверх — кредиты дороже, инфляция тормозит"},{"id":"ndfl","term":"НДФЛ (налог на доходы физических лиц)","definition":"Налог на доходы физических лиц. В учебных расчётах этого курса используются 13% до 2,4 млн ₽ годового дохода и 15% для следующей ступени. С 2025 года основная шкала прогрессивная; для других видов дохода действуют особые правила. Актуальные ставки и право на вычет проверяйте у ФНС."},{"id":"obligatsiya","term":"Облигация","definition":"долговая бумага. Ты не владелец доли, а кредитор: даёшь деньги в долг под фиксированный процент (купон), в конце срока возвращают тело долга. Риск ниже, чем у акций"},{"id":"strakhovanie-vkladov","term":"Страхование вкладов","definition":"государственная гарантия выплаты вкладчику до определённой суммы, если банк разорится. В России — 1,4 млн ₽ на банк через АСВ"},{"id":"dokhodnost","term":"Доходность","definition":"сколько процентов в год на самом деле приносит вложение при сегодняшней цене. У облигации цена и доходность ходят в разные стороны: облигация дешевеет — доходность растёт. От доходности гособлигаций отталкиваются ставки по кредитам и вкладам"},{"id":"neoblagaemyy-limit","term":"Необлагаемый лимит","definition":"сумма процентов по вкладам за год, с которой не платят НДФЛ: 1 млн ₽, умноженный на максимальную ключевую ставку за год. С процентов сверх лимита налог посчитает и пришлёт налоговая, самому подавать ничего не нужно"}],"quizzes":[{"id":"06-podushka-q1","q":"Обязательные расходы 60 000 ₽ в месяц, общие расходы 90 000 ₽. Какая минимальная подушка на 3 месяца?","options":["270 000 ₽","180 000 ₽","60 000 ₽"],"correct":1},{"id":"06-podushka-q2","q":"Почему для подушки лучше накопительный счёт с процентами на ежедневный остаток, а не на минимальный?","options":["Потому что на ежедневный остаток ставка всегда выше","Потому что такой счёт не облагается налогом","Потому что при снятии денег в середине месяца на минимальный остаток теряются проценты на снятую сумму за весь месяц"],"correct":2},{"id":"06-podushka-q3","q":"Что из этого можно считать финансовой подушкой?","options":["Деньги на накопительном счёте в банке из системы страхования вкладов","Лимит по кредитной карте","Акции крупной компании"],"correct":0}],"officialSources":[]}')}}]);